use std::fmt;

use chrono::{DateTime, Utc};
use serde_json::Value;

use super::RunId;

/// A Job's id, generated by the store.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct JobId(i64);

impl JobId {
    pub fn new(id: i64) -> Self {
        Self(id)
    }

    pub fn get(self) -> i64 {
        self.0
    }
}

impl fmt::Display for JobId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(f)
    }
}

/// What a Job does.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
#[non_exhaustive]
pub enum JobKind {
    /// Advance a Run from its Checkpoint.
    AdvanceRun,
}

impl JobKind {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::AdvanceRun => "advance_run",
        }
    }
}

/// A Job to enqueue.
#[derive(Debug, Clone, PartialEq)]
pub struct NewJob {
    pub kind: JobKind,
    pub run_id: Option<RunId>,
    pub payload: Value,
    /// When the Job becomes claimable; later than now for a delayed Job.
    pub run_at: DateTime<Utc>,
}

impl NewJob {
    /// A Job that advances `run`, claimable from `run_at`.
    pub fn advance_run(run: RunId, run_at: DateTime<Utc>) -> Self {
        Self {
            kind: JobKind::AdvanceRun,
            run_id: Some(run),
            payload: Value::Object(serde_json::Map::new()),
            run_at,
        }
    }
}

/// An enqueued Job.
#[derive(Debug, Clone, PartialEq)]
pub struct Job {
    pub id: JobId,
    pub kind: JobKind,
    pub run_id: Option<RunId>,
    pub payload: Value,
    pub run_at: DateTime<Utc>,
    pub attempts: i32,
    pub locked_by: Option<String>,
    pub locked_until: Option<DateTime<Utc>>,
    pub last_error: Option<String>,
}
